import glob, numbers, os, sys
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

def is_num(v):
    return isinstance(v, numbers.Number) and not isinstance(v, bool)

hits = sorted(glob.glob('**/budget.xlsx', recursive=True))
print('cwd:', os.getcwd())
print('budget.xlsx candidates:', hits)
if not hits:
    for p in sorted(glob.glob('**/*', recursive=True)):
        print(' file:', p)
    sys.exit('ERROR: budget.xlsx not found in workspace')

path = hits[0]
wbf = load_workbook(path, data_only=False)  # formulas / raw cells
wbv = load_workbook(path, data_only=True)   # cached calculated values

for ws in wbf.worksheets:
    wsv = wbv[ws.title]
    print(f'== Sheet {ws.title!r}  (max_row={ws.max_row}, max_column={ws.max_column})')
    gridf = [[ws.cell(r, c).value for c in range(1, ws.max_column + 1)] for r in range(1, ws.max_row + 1)]
    gridv = [[wsv.cell(r, c).value for c in range(1, wsv.max_column + 1)] for r in range(1, wsv.max_row + 1)]
    rows, cols = len(gridf), len(gridf[0]) if gridf else 0

    for r in range(rows):
        parts = []
        for c in range(cols):
            f, v = gridf[r][c], gridv[r][c]
            if f is None:
                continue
            if isinstance(f, str) and f.startswith('='):
                parts.append(f'{get_column_letter(c+1)}{r+1} ={f} (cached={v!r})')
            else:
                parts.append(f'{get_column_letter(c+1)}{r+1} = {f!r}')
        print('  ' + ' | '.join(parts))

    numeric = [(r, c, v) for r in range(rows) for c in range(cols) if is_num(gridv[r][c])]
    print(f'  numeric cells: {len(numeric)} | sum(all numeric cached values) = {sum(v for _, _, v in numeric)}')
    for c in range(cols):
        vals = [gridv[r][c] for r in range(rows) if is_num(gridv[r][c])]
        if vals:
            print(f'  col {get_column_letter(c+1)}: sum={sum(vals)} n={len(vals)} values={vals}')
    for r in range(rows):
        label = '' if gridf[r][0] is None else str(gridf[r][0])
        if 'total' in label.strip().lower():
            tot = [gridv[r][c] for c in range(cols) if is_num(gridv[r][c])]
            print(f'  total-row row {r+1} label={label!r}: values={tot}')

